// https://externalcontrollayer.ai/ns/schema/binding/oauth-presentation/1 (schemas/ecl-binding-oauth-presentation-v1.schema.json)
export type BindingOauthPresentationCompactJws = string;
/** A public JWK with its kid; private key members are refused. */
export type BindingOauthPresentationPublicJwk = {
  "kid": string;
  "kty": string;
  "crv": string;
  "x": string;
  "y"?: string;
};
/** ECL OAuth presentation record v1 OA1-010: one presentation of an OAuth access token that expresses an ECL admit, as a resource server or enforcement point retains it: the admit and its request, the token, the issuer keys the verifier configures, the presented request with its proof of possession, and whether the presentation was accepted. */
export type BindingOauthPresentation = {
  "schema_version": "ecl_oauth_presentation_v1";
  "issuer": CommonUri;
  /** OA1-007: the issuer's public keys from the verifier's own configuration. */
  "issuer_keys": {
    "keys": Array<BindingOauthPresentationPublicJwk>;
  };
  /** The identity of the resource server, which a token's aud must be. */
  "resource_server": CommonUri;
  "max_token_lifetime_seconds"?: number;
  "dpop_proof_window_seconds"?: number;
  /** OA1-003: the clock-skew allowance that the resource server applies to nbf and exp; zero when absent. */
  "clock_skew_seconds"?: number;
  "request": DcmpDecisionRequest;
  "response": DcmpDecisionResponse;
  "token": BindingOauthPresentationCompactJws;
  "presentation": {
    "method": string;
    "uri": CommonUri;
    "target": CommonUri;
    "operation": CommonAsciiToken;
    "parameters_digest": CommonDigest;
    "presented_at": CommonRfc3339Utc;
    "use_count": number;
    "dpop_proof"?: BindingOauthPresentationCompactJws;
    "client_certificate_sha256"?: string;
    "seen_dpop_jti"?: Array<string>;
  };
  /** OA1-011: the resource server's decision; a refusal names the code of the first check of the presentation table that the presentation fails. */
  "result": {
    "accepted": boolean;
    "error"?: CommonEclRegistryId;
  };
};

// https://externalcontrollayer.ai/ns/schema/binding/otel-export/1 (schemas/ecl-binding-otel-export-v1.schema.json)
/** A DCMP-2 message or an EBMP-2 event record. */
export type BindingOtelExportEclObject = DcmpMessage | EbmpEventRecord;
/** An OTLP 1.11.1 LogRecord in the JSON Protobuf encoding: 64-bit integers as decimal strings, enums as integers, identifiers in hexadecimal. */
export type BindingOtelExportLogRecord = {
  "timeUnixNano": BindingOtelExportFixed64;
  "observedTimeUnixNano": BindingOtelExportFixed64;
  "severityNumber": number;
  "severityText": string;
  "eventName": string;
  "body"?: BindingOtelExportAnyValue;
  "attributes": Array<BindingOtelExportKeyValue>;
  "droppedAttributesCount"?: number;
  "flags"?: number;
  "traceId"?: string;
  "spanId"?: string;
};
export type BindingOtelExportKeyValue = {
  "key": string;
  "value": BindingOtelExportAnyValue;
};
/** An OTLP AnyValue in the JSON Protobuf encoding, with exactly one member. A record carries no doubleValue: exchange records keep to the restricted canonical profile. */
export type BindingOtelExportAnyValue = {
  "stringValue"?: string;
  "boolValue"?: boolean;
  "intValue"?: string;
  "bytesValue"?: string;
  "arrayValue"?: {
    "values"?: Array<BindingOtelExportAnyValue>;
  };
  "kvlistValue"?: {
    "values"?: Array<BindingOtelExportKeyValue>;
  };
};
export type BindingOtelExportFixed64 = string;
/** ECL OpenTelemetry export record v1 OE1-009: one export of an ECL object as an OpenTelemetry log record, as an exporter retains it: the object it read, the OTLP log record it made in the JSON Protobuf encoding (OE1-007), the attributes the export policy declares, the outcome of the export, and the object as the evidence held it afterwards. */
export type BindingOtelExport = {
  "schema_version": "ecl_otel_export_record_v1";
  "profile": "OTEL-EVIDENCE-EXPORT-1/1.0";
  "bundle_id"?: CommonUri;
  /** OE1-005: the attributes that the export policy declares, with the data class each carries: attributes beyond the attribute table, and the table's identifiers of people and records (ecl.actor.id, ecl.subject.id, ecl.action.target), which a record carries only when they are declared; the name body declares a log record body. */
  "declared_attributes"?: Array<{
    "name": string;
    "data_class": string;
  }>;
  "object": BindingOtelExportEclObject;
  "log_record": BindingOtelExportLogRecord;
  "export": {
    "status": "exported" | "failed";
    "attempted_at": CommonRfc3339Utc;
    "error"?: string;
  };
  /** The same object as the evidence held it after the export attempt. */
  "evidence_after"?: BindingOtelExportEclObject;
};

// https://externalcontrollayer.ai/ns/schema/common/1 (schemas/ecl-common-v1.schema.json)
export type CommonAsciiToken = string;
export type CommonUri = string;
export type CommonEclRegistryId = string;
/** XR1-017: a private-use extension identifier that is an absolute URI under a namespace its owner controls; the ECL namespace is excluded. */
export type CommonPrivateExtensionUri = CommonUri;
/** XR1-017: a private-use extension identifier that is a reverse-domain token of a domain its owner controls, ending in a version; the ecl. prefix is excluded. */
export type CommonPrivateExtensionToken = string;
export type CommonExtensionId = CommonEclRegistryId | CommonPrivateExtensionUri | CommonPrivateExtensionToken;
export type CommonRfc3339Utc = string;
export type CommonSafeInteger = number;
export type CommonNonNegativeSafeInteger = number;
export type CommonBase64 = string;
export type CommonDigest = {
  "algorithm": CommonEclRegistryId;
  "value": string;
};
export type CommonPrincipal = {
  "id": CommonUri;
  "type": CommonEclRegistryId;
  "trust_domain"?: CommonUri;
  "proof_reference"?: CommonResourceReference;
};
export type CommonResourceReference = {
  "uri": CommonUri;
  "media_type"?: string;
  "version"?: CommonAsciiToken;
  "digest"?: CommonDigest;
};
export type CommonPolicyReference = {
  "id": CommonUri;
  "version": CommonAsciiToken;
  "digest": CommonDigest;
  "epoch"?: CommonNonNegativeSafeInteger;
};
export type CommonExtension = {
  "id": CommonExtensionId;
  "version": number;
  "critical": boolean;
  "value": JsonValue;
};
export type CommonExtensionSet = Array<CommonExtension>;
export type CommonIntegrityPolicy = {
  "required": boolean;
  "accepted_suites": Array<CommonEclRegistryId>;
  "eligible_key_ids"?: Array<CommonUri>;
  "required_key_ids"?: Array<CommonUri>;
  "threshold": number;
  "trust_policy": CommonPolicyReference;
  "verification_time_policy"?: CommonEclRegistryId;
  "revocation_policy"?: CommonEclRegistryId;
};
export type CommonReason = {
  "code": CommonEclRegistryId;
  "detail"?: string;
  "retryable"?: boolean;
};
export type CommonObligation = {
  "id": CommonUri;
  "type": CommonEclRegistryId;
  "value": JsonValue;
  "satisfaction": "before_release" | "during_execution" | "after_execution";
  "evidence_profile"?: CommonEclRegistryId;
};
export type CommonCausalReference = {
  "id": CommonUri;
  "digest": CommonDigest;
  "relation"?: CommonEclRegistryId;
};
export type CommonWorkflowContext = {
  "workflow_id": CommonUri;
  "root_trace_id": CommonUri;
  "parent_workflow_id"?: CommonUri;
  "attempt": CommonNonNegativeSafeInteger;
  "sequence": CommonNonNegativeSafeInteger;
  "idempotency_key"?: CommonAsciiToken;
  "causal_predecessors": Array<CommonCausalReference>;
};
/** ECL common protocol types */
export type CommonDocument = { [member: string]: JsonValue };

// https://externalcontrollayer.ai/ns/schema/conformance-claim/1 (schemas/ecl-conformance-claim-v1.schema.json)
export type ConformanceClaimIndependence = {
  "class": "A" | "B" | "C";
  "assessor": CommonResourceReference;
  "same_operator_disclosure"?: string;
};
export type ConformanceClaimVersionSet = {
  "core": CommonResourceReference;
  "companions": Array<CommonResourceReference>;
  "profiles": Array<CommonResourceReference>;
  "registries": Array<CommonResourceReference>;
};
export type ConformanceClaimCondition = {
  "condition_id": CommonUri;
  "finding_reference": CommonResourceReference;
  "remediation": string;
  "owner": CommonUri;
  "deadline": CommonRfc3339Utc;
  "operating_limit": string;
};
export type ConformanceClaimMappingClaim = {
  "framework": string;
  "framework_edition": string;
  "mapping_packet": CommonResourceReference;
  "obligation_slice": string;
  "support_class": "direct_runtime_support" | "supporting_evidence_only" | "out_of_scope";
  "residual_gap": string;
  "validation_state": "draft" | "internally_reviewed" | "independently_reviewed" | "owner_validated";
};
/** ECL Public Conformance Claim v1 */
export type ConformanceClaim = {
  "schema_version": "ecl_conformance_claim_v1";
  "claim_id": CommonUri;
  "standard_id": "ECL-1";
  "system_of_interest": CommonResourceReference;
  "level": number;
  "status": "full_conformance" | "conditional_conformance" | "assessment_only";
  "boundary_class": "full-system-mediation" | "bounded-action-class-mediation" | "component-or-profile-implementation";
  "independence": ConformanceClaimIndependence;
  "version_set": ConformanceClaimVersionSet;
  "claim_boundary": {
    "action_register": CommonResourceReference;
    "negative_boundary_annex": CommonResourceReference;
    "runtime_capability_inventory": CommonResourceReference;
    "system_boundary_diagram": CommonResourceReference;
    "trust_boundary_diagram": CommonResourceReference;
  };
  "responsibilities": Array<"decision" | "authority" | "enforcement" | "provenance" | "verification" | "fleet">;
  "deployment_profile": CommonResourceReference;
  "assessment_package": CommonResourceReference;
  "refreshed_at": CommonRfc3339Utc;
  "valid_until"?: CommonRfc3339Utc;
  "limitations": Array<string>;
  "conditions"?: Array<ConformanceClaimCondition>;
  "mapping_claims"?: Array<ConformanceClaimMappingClaim>;
  "prohibited_overclaim_attestation": {
    "liveness_guarantee": false;
    "business_outcome_guarantee": false;
    "universal_model_correctness": false;
    "automatic_legal_compliance": false;
    "framework_certification_by_mapping": false;
    "external_owner_endorsement": false;
  };
  "integrity_envelope"?: CommonResourceReference;
};

// https://externalcontrollayer.ai/ns/schema/dcmp/2 (schemas/dcmp-2.schema.json)
export type DcmpCommon = {
  "protocol": "DCMP-2";
  "schema_version": "2.0";
  "message_type": string;
  "message_id": CommonUri;
  "workflow": CommonWorkflowContext;
  "issuer": CommonPrincipal;
  "issued_at": CommonRfc3339Utc;
  "expires_at"?: CommonRfc3339Utc;
  "extensions": CommonExtensionSet;
  "integrity_policy": CommonIntegrityPolicy;
};
export type DcmpAction = {
  "action_id": CommonUri;
  "action_class": CommonEclRegistryId;
  "operation": CommonAsciiToken;
  "target": CommonResourceReference;
  "parameters"?: JsonValue;
  "parameters_digest": CommonDigest;
  "risk_class": CommonEclRegistryId;
  "required_evidence_profile": CommonEclRegistryId;
  "budget_debit"?: {
    "budget_id": CommonUri;
    "amount": string;
    "unit"?: CommonEclRegistryId;
  };
  "irreversibility_class"?: CommonEclRegistryId;
  "commit_mode"?: CommonEclRegistryId;
};
export type DcmpDecisionRequest = DcmpCommon & {
  "message_type"?: "decision_request";
  "actor": CommonPrincipal;
  "subject"?: CommonPrincipal;
  "delegation_chain"?: Array<CommonResourceReference>;
  "action": DcmpAction;
  "constraints": { [member: string]: JsonValue };
  "authority_request": {
    "audience": CommonUri;
    "requested_validity_seconds": number;
    "use_policy": "single_use" | "bounded_multi_use";
    "max_uses"?: number;
  };
  /** DCMP2-056: the request that this request continues, the decision response with outcome challenge that answered it, and the EBMP-2 human_intervention event that approved the action. */
  "continues"?: {
    "request_id": CommonUri;
    "response_id": CommonUri;
    "approval_id": CommonUri;
  };
};
export type DcmpAuthorization = {
  "authorization_id": CommonUri;
  "audience": CommonUri;
  "scope_digest": CommonDigest;
  "valid_from": CommonRfc3339Utc;
  "valid_until": CommonRfc3339Utc;
  "use_policy": "single_use" | "bounded_multi_use";
  "max_uses"?: number;
  "token_reference"?: CommonResourceReference;
};
export type DcmpDecisionResponse = DcmpCommon & {
  "message_type"?: "decision_response";
  "request_id": CommonUri;
  "decision_id": CommonUri;
  "outcome": "admit" | "deny" | "hold" | "challenge";
  "evaluated_at": CommonRfc3339Utc;
  "policy": CommonPolicyReference;
  "reasons": Array<CommonReason>;
  "obligations": Array<CommonObligation>;
  "authorization"?: DcmpAuthorization;
  "challenge_id"?: CommonUri;
  "safe_state": CommonEclRegistryId;
};
export type DcmpChallenge = DcmpCommon & {
  "message_type"?: "challenge";
  "challenge_id": CommonUri;
  "request_id": CommonUri;
  "requirements": Array<CommonObligation>;
  "deadline": CommonRfc3339Utc;
  "on_timeout": "deny" | "hold" | "restricted_mode" | "emergency_halt";
};
export type DcmpChallengeResponse = DcmpCommon & {
  "message_type"?: "challenge_response";
  "challenge_id": CommonUri;
  "request_id": CommonUri;
  "evidence": Array<CommonResourceReference>;
};
export type DcmpControlMessage = DcmpCommon & {
  "message_type"?: "control";
  "control_id": CommonUri;
  "operation": "cancel" | "revoke" | "supersede" | "quarantine" | "halt";
  "target_id": CommonUri;
  "replacement_id"?: CommonUri;
  "effective_at": CommonRfc3339Utc;
  /** DCMP2-022: the authority context of the control: the plane it is issued on and the grant under which the issuer acts. */
  "authority": {
    "plane": "ordinary" | "emergency";
    "grant": CommonResourceReference;
  };
  "reason": CommonReason;
  "safe_state"?: CommonEclRegistryId;
};
/** ECL Decision and Control Message Protocol 2 */
export type DcmpMessage = DcmpDecisionRequest | DcmpDecisionResponse | DcmpChallenge | DcmpChallengeResponse | DcmpControlMessage;

// https://externalcontrollayer.ai/ns/schema/deployment-profile/1 (schemas/ecl-deployment-profile-v1.schema.json)
export type DeploymentProfileDependency = {
  "dependency_id": CommonUri;
  "class": "local_hot_path" | "signed_cached" | "asynchronous_export" | "advisory";
  "control_state_staleness_seconds": CommonNonNegativeSafeInteger;
  "integrity_required": true;
  "failure_disposition": "degraded" | "restricted" | "quarantine" | "emergency_halt";
};
export type DeploymentProfileTimingCase = {
  "uses_default_baseline": boolean;
  "connected_revocation_seconds": CommonNonNegativeSafeInteger;
  "offline_staleness_seconds": CommonNonNegativeSafeInteger;
  "evidence_export_seconds": CommonNonNegativeSafeInteger;
  "federated_exchange_seconds"?: CommonNonNegativeSafeInteger;
  "trusted_time_or_secure_monotonic": boolean;
  "measurement_plan": CommonResourceReference;
  "variance_rationale"?: string;
  "control_assumptions"?: Array<string>;
  "residual_risk"?: string;
  /** The assessor's recorded approval of a value less strict than the default for the claim level (ECL1N-0098). */
  "assessor_deviation_approval"?: CommonResourceReference;
};
export type DeploymentProfileFallback = {
  "degraded": DeploymentProfileDegradedMode;
  "restricted": DeploymentProfileRestrictedMode;
  "emergency_halt": DeploymentProfileEmergencyMode;
  "precedence": Array<never>;
};
export type DeploymentProfileDegradedMode = {
  "entry_conditions": DeploymentProfileNonEmptyStrings;
  "signed_cached_state_required": true;
  "bounded_actions": DeploymentProfileNonEmptyStrings;
  "expires_to": "restricted" | "emergency_halt";
};
export type DeploymentProfileRestrictedMode = {
  "entry_conditions": DeploymentProfileNonEmptyStrings;
  "allowed_actions": Array<"diagnose" | "recover" | "contain" | "safe_shutdown">;
};
export type DeploymentProfileEmergencyMode = {
  "entry_conditions": DeploymentProfileNonEmptyStrings;
  "release_allowed": false;
  "separately_authenticated": true;
};
export type DeploymentProfileEvidenceCustody = {
  "local_append_only_buffer": true;
  "export_integrity": true;
  "retention_profile": CommonResourceReference;
  "independent_verification_path": CommonResourceReference;
  "transfer_custody"?: CommonResourceReference;
};
export type DeploymentProfileTopologyControls = {
  "centralized"?: {
    "low_latency_policy_distribution": true;
    "central_audit": true;
    "rapid_revocation": true;
  };
  "federated"?: {
    "trust_bundle_exchange": CommonResourceReference;
    "delegation_semantics": CommonResourceReference;
    "cross_domain_verification": CommonResourceReference;
    "authority_context_fields": DeploymentProfileFederatedFields;
  };
  "sovereign"?: {
    "local_policy_control": true;
    "local_key_control": true;
    "local_evidence_control": true;
    "residency_boundary": CommonUri;
  };
  "offline"?: {
    "policy_cache_staleness_seconds": CommonNonNegativeSafeInteger;
    "trust_cache_staleness_seconds": CommonNonNegativeSafeInteger;
    "stale_transition": "restricted" | "emergency_halt" | "quarantine";
    "reconnect_reconciliation": CommonResourceReference;
  };
  "air_gapped"?: {
    "update_media_integrity": CommonResourceReference;
    "export_integrity": CommonResourceReference;
    "emergency_policy_dual_control": CommonResourceReference;
    "disconnected_revocation_workflow": CommonResourceReference;
    "disconnected_incident_workflow": CommonResourceReference;
  };
};
export type DeploymentProfileFederatedFields = Array<"trust_domain" | "issuer_or_trust_bundle" | "decision_contract_version" | "root_trace_id" | "actor" | "subject" | "authorization_or_capability" | "resource_scope" | "expiry" | "policy_reference" | "evidence_profile" | "unique_token_id" | "delegation_depth">;
export type DeploymentProfileNonEmptyStrings = Array<string>;
/** ECL Deployment Profile v1 */
export type DeploymentProfile = {
  "schema_version": "ecl_deployment_profile_v1";
  "profile_id": CommonUri;
  "profile_version": CommonAsciiToken;
  "profile_digest": CommonDigest;
  "system_of_interest": CommonResourceReference;
  "claim_level": number;
  "model": "centralized-distributed-enforcement" | "federated-multi-domain" | "sovereign-self-managed" | "offline-edge" | "air-gapped-segmented";
  "delivery_surfaces": Array<"local_gate" | "hosted_control_plane" | "self_managed_control_plane" | "offline_verifier" | "air_gap_transfer_station">;
  "release_path": {
    "enforcement_location": "in_process" | "same_host_sidecar" | "local_network_appliance";
    "remote_dependency_in_hot_path": false;
    "signed_local_or_cached_state": true;
    "decision_timeout_milliseconds": number;
    "network_loss_disposition": "bounded_degraded_then_restricted" | "bounded_degraded_then_emergency_halt" | "immediate_restricted" | "immediate_emergency_halt";
  };
  "dependencies": Array<DeploymentProfileDependency>;
  "timing_case": DeploymentProfileTimingCase;
  "fallback": DeploymentProfileFallback;
  "evidence_custody": DeploymentProfileEvidenceCustody;
  "topology_controls": DeploymentProfileTopologyControls;
  "sector_profile_references"?: Array<CommonResourceReference>;
  "residual_risks"?: Array<string>;
};

// https://externalcontrollayer.ai/ns/schema/ebmp/2 (schemas/ebmp-2.schema.json)
export type EbmpCommon = {
  "protocol": "EBMP-2";
  "schema_version": "2.0";
  "object_type": string;
  "object_id": CommonUri;
  "workflow": CommonWorkflowContext;
  "producer": CommonPrincipal;
  "observed_at": CommonRfc3339Utc;
  "monotonic_observation"?: {
    "clock_id": CommonUri;
    "ticks": string;
    "unit": "nanosecond" | "microsecond" | "millisecond";
  };
  "extensions": CommonExtensionSet;
  "integrity_policy": CommonIntegrityPolicy;
};
export type EbmpEventRecord = EbmpCommon & {
  "object_type"?: "event_record";
  "event_type": "request_received" | "decision_recorded" | "authority_issued" | "authority_consumed" | "release_prepared" | "execution_released" | "execution_observed" | "execution_terminal" | "human_intervention" | "verification" | "safe_state_transition" | "fleet_transition" | "lifecycle_transition";
  "event": EbmpRequestEvent | EbmpDecisionEvent | EbmpAuthorityEvent | EbmpExecutionEvent | EbmpInterventionEvent | EbmpVerificationEvent | EbmpStateEvent | EbmpLifecycleEvent;
};
export type EbmpRequestEvent = {
  "kind": "request";
  "request": CommonResourceReference;
};
export type EbmpDecisionEvent = {
  "kind": "decision";
  "decision": CommonResourceReference;
  "outcome": "admit" | "deny" | "hold" | "challenge";
  "policy": CommonPolicyReference;
  "reasons"?: Array<CommonReason>;
};
export type EbmpAuthorityEvent = {
  "kind": "authority";
  "authorization_id": CommonUri;
  "state": "issued" | "active" | "consumed" | "revoked" | "expired" | "superseded";
  "authority"?: CommonResourceReference;
  "use_count"?: CommonNonNegativeSafeInteger;
};
export type EbmpExecutionEvent = {
  "kind": "execution";
  "action_id": CommonUri;
  "attempt_id": CommonUri;
  "state": "not_started" | "prepared" | "released" | "running" | "succeeded" | "failed" | "partially_succeeded" | "cancelled" | "timed_out" | "rolled_back" | "compensated" | "unknown" | "denied" | "held" | "challenged" | "expired_before_release";
  "decision"?: CommonResourceReference;
  "authority"?: CommonResourceReference;
  "target"?: CommonResourceReference;
  "operation"?: CommonAsciiToken;
  "parameters_digest"?: CommonDigest;
  "result"?: CommonResourceReference;
  "side_effects"?: Array<CommonResourceReference>;
  "residual_state"?: string;
  /** EBMP2-071: on an execution_released event, the enforcement point's declared bound, in milliseconds, on the delay from the final observation that observed_at records to the release (the release guard its profile declares). A verifier adds it to observed_at when it tests the release against the authorization's valid_until (EBMP2-050). Required on execution_released and not carried by any other execution event. */
  "release_guard_ms"?: number;
};
export type EbmpInterventionEvent = {
  "kind": "intervention";
  "intervention_id": CommonUri;
  "actor": CommonPrincipal;
  "operation": "approve" | "reject" | "cancel" | "quarantine" | "halt" | "release" | "override";
  "target_id": CommonUri;
  "authority": CommonResourceReference;
  "issued_at": CommonRfc3339Utc;
  "expires_at": CommonRfc3339Utc;
  "reason": CommonReason;
};
export type EbmpVerificationEvent = {
  "kind": "verification";
  "verifier": CommonPrincipal;
  "subject": CommonResourceReference;
  "decision": "pass" | "fail" | "indeterminate";
  "rules": Array<CommonEclRegistryId>;
  "findings": Array<CommonReason>;
  /** EBMP2-019: the registry versions the verifier applied, as an immutable digest-bound reference. */
  "registry_snapshot": CommonResourceReference;
  /** EBMP2-019: what the verifier observed and could not observe. */
  "evidence_boundary": string;
};
export type EbmpStateEvent = {
  "kind": "state";
  "scope": CommonUri;
  "prior_state": CommonEclRegistryId;
  "new_state": CommonEclRegistryId;
  "trigger": CommonReason;
  "frontiers"?: { [member: string]: JsonValue };
};
export type EbmpLifecycleEvent = {
  "kind": "lifecycle";
  "subject": CommonResourceReference;
  "operation": "seal" | "verify" | "verification_fail" | "retain" | "export" | "redact" | "supersede" | "revoke" | "legal_hold" | "release_hold" | "destroy";
  "policy": CommonPolicyReference;
  "prior_digest": CommonDigest;
  "derived_artifact"?: CommonResourceReference;
  "redaction_manifest"?: CommonResourceReference;
  "destruction_proof"?: CommonResourceReference;
};
export type EbmpBundleManifest = EbmpCommon & {
  "object_type"?: "bundle_manifest";
  "bundle_profile": CommonEclRegistryId;
  "records": Array<CommonResourceReference>;
  "closure": {
    "status": "complete" | "incomplete" | "indeterminate";
    "terminal_action_ids": Array<CommonUri>;
    "open_action_ids": Array<CommonUri>;
    "unresolved_predecessor_ids": Array<CommonUri>;
  };
  "registry_snapshot"?: CommonResourceReference;
  "trust_bundle"?: CommonResourceReference;
};
/** ECL Evidence Bundle and Manifest Protocol 2 */
export type EbmpObject = EbmpEventRecord | EbmpBundleManifest;

// https://externalcontrollayer.ai/ns/schema/evidence-bundle/1 (schemas/ecl-evidence-bundle-v1.schema.json)
/** ECL Evidence Bundle v1 An offline-verifiable collection of signed ECL decisions, evidence events, and optional observations. */
export type EvidenceBundle = {
  "schema_version": "ecl_evidence_bundle_v1";
  "envelopes": Array<IntegrityEnvelope>;
  "observations"?: Array<IntegrityEnvelope>;
};

